        "use strict";
        var b = a.i(87924);
        let c = [{ step: "01", stepAr: "\u0660\u0661", name: "Discover", nameArabic: "\u0627\u0644\u0627\u0633\u062A\u0643\u0634\u0627\u0641 \u0648\u0627\u0644\u062A\u062D\u0644\u064A\u0644", tagline: "Uncover real constraints before proposing solutions.", taglineAr: "\u0641\u0647\u0645 \u0627\u0644\u0642\u064A\u0648\u062F \u0648\u0627\u0644\u0641\u0631\u0635 \u0627\u0644\u062D\u0642\u064A\u0642\u064A\u0629 \u0642\u0628\u0644 \u0627\u0642\u062A\u0631\u0627\u062D \u0623\u064A \u062D\u0644\u0648\u0644 \u062A\u0642\u0646\u064A\u0629.", description: "We begin every engagement by interrogating the core problem: technical bottlenecks, operational friction, user expectations, and business objectives. We do not jump into Figma or write code until the problem boundary is sharp.", descriptionAr: "\u0646\u0628\u062F\u0623 \u0643\u0644 \u0645\u0634\u0631\u0648\u0639 \u0628\u062A\u062D\u0644\u064A\u0644 \u0639\u0645\u064A\u0642 \u0644\u062C\u0630\u0648\u0631 \u0627\u0644\u0645\u0634\u0643\u0644\u0629: \u0627\u0644\u0627\u062E\u062A\u0646\u0627\u0642\u0627\u062A \u0627\u0644\u062A\u0642\u0646\u064A\u0629\u060C \u0648\u0646\u0642\u0627\u0637 \u0627\u0644\u0647\u062F\u0631 \u0627\u0644\u062A\u0634\u063A\u064A\u0644\u064A\u060C \u0648\u0633\u0644\u0648\u0643 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646\u060C \u0648\u0623\u0647\u062F\u0627\u0641 \u0627\u0644\u0639\u0645\u0644. \u0644\u0627 \u0646\u0628\u062F\u0623 \u0641\u064A \u0627\u0644\u062A\u0635\u0645\u064A\u0645 \u0623\u0648 \u0643\u062A\u0627\u0628\u0629 \u0627\u0644\u0643\u0648\u062F \u0625\u0644\u0627 \u0628\u0639\u062F \u0648\u0636\u0648\u062D \u0646\u0637\u0627\u0642 \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u062A\u0645\u0627\u0645\u064B\u0627.", activities: ["Technical environment & API infrastructure audit", "Key stakeholder and user workflow interviews", "Competitive positioning and market benchmark review", "Risk assessment and dependency identification"], activitiesAr: ["\u062A\u062F\u0642\u064A\u0642 \u0627\u0644\u0628\u0646\u064A\u0629 \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0629 \u0648\u062C\u0627\u0647\u0632\u064A\u0629 \u0648\u0627\u062C\u0647\u0627\u062A \u0627\u0644\u0623\u0646\u0638\u0645\u0629", "\u0645\u0642\u0627\u0628\u0644\u0627\u062A \u0645\u0643\u062B\u0641\u0629 \u0645\u0639 \u0623\u0635\u062D\u0627\u0628 \u0627\u0644\u0645\u0635\u0644\u062D\u0629 \u0648\u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u064A\u0646", "\u062A\u062D\u0644\u064A\u0644 \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u064A\u0646 \u0648\u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0633\u0648\u0642 \u0627\u0644\u0645\u0633\u062A\u0647\u062F\u0641\u0629", "\u062A\u062D\u062F\u064A\u062F \u0627\u0644\u0645\u062E\u0627\u0637\u0631 \u0648\u0627\u0644\u0627\u0639\u062A\u0645\u0627\u062F\u064A\u0627\u062A \u0627\u0644\u062A\u0642\u0646\u064A\u0629 \u0627\u0644\u0645\u0633\u0628\u0642\u0629"], deliverable: "Discovery Synthesis & Technical Feasibility Brief", deliverableAr: "\u0648\u062B\u064A\u0642\u0629 \u0645\u062E\u0631\u062C\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u0643\u0634\u0627\u0641 \u0648\u062F\u0631\u0627\u0633\u0629 \u0627\u0644\u062C\u062F\u0648\u0649 \u0627\u0644\u0641\u0646\u064A\u0629", duration: "Week 1", durationAr: "\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u0623\u0648\u0644" }, { step: "02", stepAr: "\u0660\u0662", name: "Plan", nameArabic: "\u0627\u0644\u062A\u062E\u0637\u064A\u0637 \u0648\u0627\u0644\u0647\u0646\u062F\u0633\u0629", tagline: "Define exact scope, milestones, and architectural direction.", taglineAr: "\u062A\u062D\u062F\u064A\u062F \u0646\u0637\u0627\u0642 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u062F\u0642\u064A\u0642 \u0648\u0627\u0644\u0645\u0631\u0627\u062D\u0644 \u0648\u0627\u0644\u0645\u0639\u0645\u0627\u0631\u064A\u0629 \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0629.", description: "Ambiguity is the single greatest cause of software failure and project budget overruns. In this stage, we lock down user flows, system specifications, data models, and an exact milestone calendar.", descriptionAr: "\u0627\u0644\u063A\u0645\u0648\u0636 \u0647\u0648 \u0627\u0644\u0633\u0628\u0628 \u0627\u0644\u0631\u0626\u064A\u0633\u064A \u0644\u0641\u0634\u0644 \u0627\u0644\u0628\u0631\u0645\u062C\u064A\u0627\u062A \u0648\u062A\u062C\u0627\u0648\u0632 \u0627\u0644\u0645\u064A\u0632\u0627\u0646\u064A\u0627\u062A. \u0641\u064A \u0647\u0630\u0647 \u0627\u0644\u0645\u0631\u062D\u0644\u0629\u060C \u0646\u062D\u0643\u0645 \u0645\u0633\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645\u060C \u0648\u0645\u0648\u0627\u0635\u0641\u0627\u062A \u0627\u0644\u0646\u0638\u0627\u0645\u060C \u0648\u0646\u0645\u0627\u0630\u062C \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A\u060C \u0648\u062C\u062F\u0648\u0644 \u0627\u0644\u062A\u0633\u0644\u064A\u0645 \u0627\u0644\u0632\u0645\u0646\u064A.", activities: ["Information architecture and database schema design", "API contract definition and third-party integration mapping", "Sprint roadmap and milestone timeline allocation", "Resource allocation and security baseline definition"], activitiesAr: ["\u0647\u0646\u062F\u0633\u0629 \u0627\u0644\u0645\u0639\u0644\u0648\u0645\u0627\u062A \u0648\u062A\u0635\u0645\u064A\u0645 \u0647\u064A\u0643\u0644 \u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A", "\u062A\u0648\u062B\u064A\u0642 \u0645\u0648\u0627\u0635\u0641\u0627\u062A \u0648\u0627\u062C\u0647\u0627\u062A \u0627\u0644\u0631\u0628\u0637 (API Contracts)", "\u062E\u0627\u0631\u0637\u0629 \u0637\u0631\u064A\u0642 \u062F\u0648\u0631\u0627\u062A \u0627\u0644\u062A\u0637\u0648\u064A\u0631 (Sprints) \u0648\u0645\u0648\u0627\u0639\u064A\u062F \u0627\u0644\u062A\u0633\u0644\u064A\u0645", "\u062A\u062D\u062F\u064A\u062F \u0645\u0639\u0627\u064A\u064A\u0631 \u0627\u0644\u0623\u0645\u0627\u0646 \u0648\u0636\u0648\u0627\u0628\u0637 \u0627\u0644\u0635\u0644\u0627\u062D\u064A\u0627\u062A"], deliverable: "Product Architecture Blueprint & Scope Matrix", deliverableAr: "\u0627\u0644\u0645\u062E\u0637\u0637 \u0627\u0644\u0645\u0639\u0645\u0627\u0631\u064A \u0644\u0644\u0645\u0646\u062A\u062C \u0648\u0645\u0635\u0641\u0648\u0641\u0629 \u0646\u0637\u0627\u0642 \u0627\u0644\u0639\u0645\u0644", duration: "Week 1 \u2013 2", durationAr: "\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0661 \u2013 \u0662" }, { step: "03", stepAr: "\u0660\u0663", name: "Design", nameArabic: "\u0627\u0644\u062A\u0635\u0645\u064A\u0645 \u0648\u062A\u062C\u0631\u0628\u0629 \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645", tagline: "Build the visual system and user experience with rigorous intention.", taglineAr: "\u0628\u0646\u0627\u0621 \u0648\u0627\u062C\u0647\u0627\u062A \u0627\u0644\u0627\u0633\u062A\u062E\u062F\u0627\u0645 \u0648\u0627\u0644\u0646\u0638\u0627\u0645 \u0627\u0644\u0628\u0635\u0631\u064A \u0628\u0648\u0639\u064A \u0647\u0646\u062F\u0633\u064A \u062F\u0642\u064A\u0642.", description: "Design at RAWAFD is an engineering discipline. We create comprehensive Figma design systems, tactile interactive prototypes, and typography scales that directly map to production code tokens.", descriptionAr: "\u0627\u0644\u062A\u0635\u0645\u064A\u0645 \u0641\u064A \u0631\u0648\u0627\u0641\u062F \u0645\u0645\u0627\u0631\u0633\u0629 \u0647\u0646\u062F\u0633\u064A\u0629 \u0642\u0627\u0626\u0645\u0629 \u0639\u0644\u0649 \u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637. \u0646\u0624\u0633\u0633 \u0646\u0638\u0645 \u062A\u0635\u0645\u064A\u0645 \u0645\u062A\u0643\u0627\u0645\u0644\u0629 \u0641\u064A \u0641\u064A\u063A\u0645\u0627\u060C \u0648\u0646\u0645\u0627\u0630\u062C \u062A\u0641\u0627\u0639\u0644\u064A\u0629 \u062D\u064A\u0629\u060C \u0648\u0645\u0642\u0627\u064A\u064A\u0633 \u062E\u0637\u0648\u0637 \u062A\u0631\u062A\u0628\u0637 \u0645\u0628\u0627\u0634\u0631\u0629 \u0628\u0645\u062A\u063A\u064A\u0631\u0627\u062A \u0627\u0644\u0643\u0648\u062F \u0627\u0644\u0641\u0639\u0644\u064A.", activities: ["Wireframe exploration and user journey optimization", "Figma design token architecture (color, type, elevation, spacing)", "High-fidelity desktop, tablet, and mobile interface design", "Clickable interactive prototypes for stakeholder validation"], activitiesAr: ["\u062A\u0637\u0648\u064A\u0631 \u0627\u0644\u0645\u062E\u0637\u0637\u0627\u062A \u0627\u0644\u0647\u064A\u0643\u0644\u064A\u0629 \u0648\u062A\u062D\u0633\u064A\u0646 \u0645\u0633\u0627\u0631\u0627\u062A \u0627\u0644\u0645\u0633\u062A\u062E\u062F\u0645", "\u062A\u0623\u0633\u064A\u0633 \u0645\u0643\u062A\u0628\u0629 \u0627\u0644\u0645\u062A\u063A\u064A\u0631\u0627\u062A \u0627\u0644\u062A\u0635\u0645\u064A\u0645\u064A\u0629 \u0641\u064A \u0641\u064A\u063A\u0645\u0627", "\u062A\u0635\u0645\u064A\u0645 \u0627\u0644\u0648\u0627\u062C\u0647\u0627\u062A \u0639\u0627\u0644\u064A\u0629 \u0627\u0644\u062F\u0642\u0629 \u0644\u0643\u0627\u0641\u0629 \u0645\u0642\u0627\u0633\u0627\u062A \u0627\u0644\u0634\u0627\u0634\u0627\u062A", "\u0628\u0646\u0627\u0621 \u0646\u0645\u0648\u0630\u062C \u062A\u0641\u0627\u0639\u0644\u064A \u062D\u064A \u0644\u0627\u062E\u062A\u0628\u0627\u0631 \u0627\u0644\u062A\u062C\u0631\u0628\u0629 \u0648\u0627\u0644\u0645\u0635\u0627\u062F\u0642\u0629"], deliverable: "Validated Interactive Prototype & Design Token System", deliverableAr: "\u0627\u0644\u0646\u0645\u0648\u0630\u062C \u0627\u0644\u062A\u0641\u0627\u0639\u0644\u064A \u0627\u0644\u0645\u0639\u062A\u0645\u062F \u0648\u0646\u0638\u0627\u0645 \u0639\u0646\u0627\u0635\u0631 \u0627\u0644\u062A\u0635\u0645\u064A\u0645", duration: "Week 2 \u2013 4", durationAr: "\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0662 \u2013 \u0664" }, { step: "04", stepAr: "\u0660\u0664", name: "Build", nameArabic: "\u0627\u0644\u062A\u0637\u0648\u064A\u0631 \u0648\u0627\u0644\u062A\u0646\u0641\u064A\u0630", tagline: "Write clean, type-safe code and resilient automation pipelines.", taglineAr: "\u0643\u062A\u0627\u0628\u0629 \u0643\u0648\u062F \u0628\u0631\u0645\u062C\u064A \u0645\u062D\u0643\u0645 \u0648\u0628\u0646\u0627\u0621 \u0645\u0633\u0627\u0631\u0627\u062A \u0623\u062A\u0645\u062A\u0629 \u0634\u062F\u064A\u062F\u0629 \u0627\u0644\u0627\u0633\u062A\u0642\u0631\u0627\u0631.", description: "Our engineering team translates validated designs into production code. We work in disciplined weekly sprints with transparent progress updates, staging environments, and zero handoff friction.", descriptionAr: "\u064A\u062A\u0631\u062C\u0645 \u0641\u0631\u064A\u0642\u0646\u0627 \u0627\u0644\u0647\u0646\u062F\u0633\u064A \u0627\u0644\u062A\u0635\u0627\u0645\u064A\u0645 \u0627\u0644\u0645\u0639\u062A\u0645\u062F\u0629 \u0625\u0644\u0649 \u0643\u0648\u062F \u0625\u0646\u062A\u0627\u062C\u064A \u0633\u0631\u064A\u0639 \u0648\u0622\u0645\u0646. \u0646\u0639\u0645\u0644 \u0628\u062F\u0648\u0631\u0627\u062A \u0623\u0633\u0628\u0648\u0639\u064A\u0629 \u0645\u062D\u062F\u062F\u0629 \u0645\u0639 \u0625\u062A\u0627\u062D\u0629 \u0628\u064A\u0626\u0629 \u062A\u062C\u0631\u064A\u0628\u064A\u0629 \u0633\u062D\u0627\u0628\u064A\u0629 \u0648\u062A\u0642\u0627\u0631\u064A\u0631 \u0625\u0646\u062C\u0627\u0632 \u0634\u0641\u0627\u0641\u0629 \u0623\u0633\u0628\u0648\u0639\u064A\u064B\u0627.", activities: ["Frontend component engineering with TypeScript and modern frameworks", "Backend API development, database migrations, and caching layers", "AI model orchestration, prompt engineering, and automation triggers", "Continuous integration, automated unit testing, and code reviews"], activitiesAr: ["\u0628\u0646\u0627\u0621 \u0627\u0644\u0648\u0627\u062C\u0647\u0627\u062A \u0627\u0644\u0623\u0645\u0627\u0645\u064A\u0629 \u0627\u0644\u0645\u0639\u064A\u0627\u0631\u064A\u0629 \u0628\u0640 Next.js \u0648 TypeScript", "\u062A\u0637\u0648\u064A\u0631 \u0648\u0627\u062C\u0647\u0627\u062A \u0627\u0644\u0628\u0627\u0643 \u0625\u0646\u062F \u0648\u0642\u0648\u0627\u0639\u062F \u0627\u0644\u0628\u064A\u0627\u0646\u0627\u062A \u0648\u0637\u0628\u0642\u0627\u062A \u0627\u0644\u062A\u062E\u0632\u064A\u0646 \u0627\u0644\u0645\u0624\u0642\u062A", "\u062A\u0641\u0639\u064A\u0644 \u0646\u0645\u0627\u0630\u062C \u0627\u0644\u0630\u0643\u0627\u0621 \u0627\u0644\u0627\u0635\u0637\u0646\u0627\u0639\u064A \u0648\u0631\u0628\u0637 \u0645\u062D\u0641\u0632\u0627\u062A \u0627\u0644\u0623\u062A\u0645\u062A\u0629", "\u0641\u062D\u0635 \u0622\u0644\u064A \u0645\u0633\u062A\u0645\u0631 \u0648\u0645\u0631\u0627\u062C\u0639\u0629 \u0623\u0642\u0631\u0627\u0646 \u0644\u0643\u0627\u0641\u0629 \u0623\u0633\u0637\u0631 \u0627\u0644\u0643\u0648\u062F \u0627\u0644\u0628\u0631\u0645\u062C\u064A"], deliverable: "Staging Environment Build & Weekly Sprint Review Access", deliverableAr: "\u0646\u0633\u062E\u0629 \u0628\u064A\u0626\u0629 \u0627\u0644\u0645\u0639\u0627\u064A\u0646\u0629 \u0627\u0644\u062D\u064A\u0629 \u0648\u0627\u0633\u062A\u0639\u0631\u0627\u0636 \u0623\u0633\u0628\u0648\u0639\u064A \u0644\u0644\u0625\u0646\u062C\u0627\u0632", duration: "Week 3 \u2013 8+", durationAr: "\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0663 \u2013 \u0668+" }, { step: "05", stepAr: "\u0660\u0665", name: "Refine", nameArabic: "\u0627\u0644\u062A\u062D\u0633\u064A\u0646 \u0648\u0627\u0644\u0625\u0637\u0644\u0627\u0642", tagline: "Stress-test, optimize performance, and deploy with confidence.", taglineAr: "\u0641\u062D\u0635 \u0627\u0644\u0636\u063A\u0637\u060C \u0648\u062A\u062D\u0633\u064A\u0646 \u0627\u0644\u0633\u0631\u0639\u0629\u060C \u0648\u0627\u0644\u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0631\u0633\u0645\u064A \u0628\u0643\u0644 \u062B\u0642\u0629.", description: "Before public release, we subject the build to rigorous quality assurance: device matrix testing, accessibility checks, Core Web Vitals optimization, and security audits.", descriptionAr: "\u0642\u0628\u0644 \u0627\u0644\u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0631\u0633\u0645\u064A \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u060C \u0646\u062E\u0636\u0639 \u0627\u0644\u0646\u0638\u0627\u0645 \u0644\u0627\u062E\u062A\u0628\u0627\u0631\u0627\u062A \u062C\u0648\u062F\u0629 \u0635\u0627\u0631\u0645\u0629: \u0641\u062D\u0635 \u0627\u0644\u062A\u0648\u0627\u0641\u0642 \u0639\u0644\u0649 \u0627\u0644\u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0645\u062A\u0646\u0648\u0639\u0629\u060C \u0648\u062A\u062F\u0642\u064A\u0642 \u0627\u0644\u0648\u0635\u0648\u0644\u064A\u0629\u060C \u0648\u062A\u062D\u0633\u064A\u0646 \u0633\u0631\u0639\u0629 \u0627\u0644\u0627\u0633\u062A\u062C\u0627\u0628\u0629\u060C \u0648\u0641\u062D\u0635 \u0627\u0644\u0623\u0645\u0627\u0646.", activities: ["Cross-browser and multi-device responsive verification", "Core Web Vitals profiling and network latency optimization", "Production deployment, DNS cutover, and automated backup setup", "Comprehensive handover runbooks and team operational training"], activitiesAr: ["\u0627\u0644\u062A\u062D\u0642\u0642 \u0645\u0646 \u0627\u0644\u062A\u0648\u0627\u0641\u0642 \u0639\u0628\u0631 \u0645\u062E\u062A\u0644\u0641 \u0627\u0644\u0645\u062A\u0635\u0641\u062D\u0627\u062A \u0648\u0627\u0644\u0623\u062C\u0647\u0632\u0629 \u0627\u0644\u0645\u062D\u0645\u0648\u0644\u0629", "\u062A\u062D\u0633\u064A\u0646 \u0633\u0631\u0639\u0629 \u0627\u0644\u062A\u062D\u0645\u064A\u0644 \u0648\u062A\u0642\u0644\u064A\u0644 \u0627\u0633\u062A\u0647\u0644\u0627\u0643 \u0645\u0648\u0627\u0631\u062F \u0627\u0644\u0633\u064A\u0631\u0641\u0631", "\u0627\u0644\u0646\u0634\u0631 \u0639\u0644\u0649 \u0627\u0644\u062E\u0648\u0627\u062F\u0645 \u0627\u0644\u0625\u0646\u062A\u0627\u062C\u064A\u0629 \u0648\u062A\u0641\u0639\u064A\u0644 \u0627\u0644\u0646\u0633\u062E \u0627\u0644\u0627\u062D\u062A\u064A\u0627\u0637\u064A \u0627\u0644\u062A\u0644\u0642\u0627\u0626\u064A", "\u062A\u0633\u0644\u064A\u0645 \u062F\u0644\u064A\u0644 \u0627\u0644\u062A\u0634\u063A\u064A\u0644 \u0627\u0644\u0634\u0627\u0645\u0644 \u0648\u062A\u062F\u0631\u064A\u0628 \u0627\u0644\u0641\u0631\u064A\u0642 \u0627\u0644\u062F\u0627\u062E\u0644\u064A"], deliverable: "Live Production Deployment & Post-Launch Support Runbook", deliverableAr: "\u0627\u0644\u0625\u0637\u0644\u0627\u0642 \u0627\u0644\u0625\u0646\u062A\u0627\u062C\u064A \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0648\u062F\u0644\u064A\u0644 \u0627\u0644\u062F\u0639\u0645 \u0648\u0627\u0644\u062A\u0634\u063A\u064A\u0644", duration: "Final 1 \u2013 2 Weeks", durationAr: "\u0627\u0644\u0623\u0633\u0628\u0648\u0639 \u0627\u0644\u0623\u062E\u064A\u0631" }];
